import{register}from"@elementor/frontend-handlers";const initAccordion=e=>{const a=e.querySelectorAll(".aae-a-accordion-item");if(!a.length)return;const t=e.dataset.maxItemsExpanded||"one",c=e.dataset.defaultState||"first";a.forEach(e=>{const i=e.querySelector(".aae-accordion-header"),s=e.querySelector(".aae-accordion-content");if(!i||!s)return;const r=e===a[0];"first"===c&&r&&!e.classList.contains("active")?(e.classList.add("active"),i.setAttribute("aria-expanded","true")):"none"===c&&e.classList.contains("active")&&(e.classList.remove("active"),i.setAttribute("aria-expanded","false")),i.addEventListener("click",()=>{const c=e.classList.contains("active");"one"!==t||c||a.forEach(a=>{a!==e&&a.classList.contains("active")&&(a.classList.remove("active"),a.querySelector(".aae-accordion-header").setAttribute("aria-expanded","false"))}),c?(e.classList.remove("active"),i.setAttribute("aria-expanded","false")):(e.classList.add("active"),i.setAttribute("aria-expanded","true"))})})};register({elementType:"e-aae-a-accordion",id:"aae-a-accordion-handler",callback:({element:e})=>{const a=e.classList.contains("aae-a-accordion")?e:e.querySelector(".aae-a-accordion");a&&initAccordion(a)}});